{"path": "units/rules/engine.py", "content": "def evaluate(rules, facts):
    """对 facts 求值规则。

    - {"all": [k, ...]}：所有列出的键在 facts 中为真时才返回 True。
    - {"any": [k, ...]}：任一列出的键为真即返回 True。
    - 其它形状返回 False。
    返回真正的 bool。
    """
    if "all" in rules:
        return all(bool(facts.get(key)) for key in rules["all"])
    if "any" in rules:
        return any(bool(facts.get(key)) for key in rules["any"])
    return False
"}

{"path": "units/ledger/ledger.py", "content": """"一个只关心单个账户的小账本。"""

VALID_KINDS = ("deposit", "withdraw")


class Ledger:
    def apply(self, rows, op):
        """rows 是 [(kind, account, cents), ...]，返回**该账户**的行（保持原顺序）。

        - kind 只有 "deposit" 与 "withdraw"，其它值抛 ValueError。
        - 金额 (cents) 为负时抛 ValueError（对任意账户都先做校验）。
        """
        for row in rows:
            kind, _account, cents = row
            if kind not in VALID_KINDS:
                raise ValueError(f"unknown kind: {kind!r}")
            if cents < 0:
                raise ValueError(f"negative amount: {cents!r}")
        return [row for row in rows if row[1] == op]


def balance(rows, account):
    """返回该账户的净额：deposit 相加、withdraw 相减；没有该账户的行时返回 0。"""
    total = 0
    for kind, acct, cents in rows:
        if acct != account:
            continue
        if kind == "deposit":
            total += cents
        elif kind == "withdraw":
            total -= cents
        else:
            raise ValueError(f"unknown kind: {kind!r}")
    return total
"}

{"path": "units/schedule/schedule.py", "content": """"闭区间的时间段工具。"""


def _normalize(ranges):
    return sorted((min(a, b), max(a, b)) for a, b in ranges)


def slots(ranges, minutes):
    """合并闭区间：两段之间的空隙（next_lo - prev_hi）小于 minutes 视为同一段。

    返回按起点升序的合并结果；空输入返回 []。
    """
    if not ranges:
        return []
    merged = [list(_normalize(ranges)[0])]
    for lo, hi in _normalize(ranges)[1:]:
        if lo - merged[-1][1] < minutes:
            if hi > merged[-1][1]:
                merged[-1][1] = hi
        else:
            merged.append([lo, hi])
    return [(lo, hi) for lo, hi in merged]


def overlaps(a, b):
    """两个闭区间是否有交叠；端点正好相接（如 (0,10) 与 (10,20)）不算交叠。"""
    if a[1] == b[0] or b[1] == a[0]:
        return False
    return a[0] <= b[1] and b[0] <= a[1]
"}

{"path": "units/intervals/intervals.py", "content": """"闭区间工具（整数端点，lo <= hi）。"""


class Impl:
    def merge(self, ranges, gap=0):
        """合并闭区间：按 lo 升序排序后，若相邻两段之间**缺失的整数个数**
        （next.lo - prev.hi - 1）小于等于 gap 就合并。返回 [(lo, hi), ...] 升序；空输入返回 []。
        """
        if not ranges:
            return []
        ordered = sorted((min(a, b), max(a, b)) for a, b in ranges)
        merged = [list(ordered[0])]
        for lo, hi in ordered[1:]:
            missing = lo - merged[-1][1] - 1
            if missing <= gap:
                if hi > merged[-1][1]:
                    merged[-1][1] = hi
            else:
                merged.append([lo, hi])
        return [(lo, hi) for lo, hi in merged]

    def subtract(self, ranges, hole):
        """从 ranges 中挖去闭区间 hole：返回剩下的闭区间（升序）。

        与 hole 不相交的段原样保留，被完全覆盖的段消失，横跨 hole 的段分裂成两段。
        """
        merged = self.merge(ranges)
        hlo, hhi = min(hole), max(hole)
        out = []
        for lo, hi in merged:
            if hi < hlo or lo > hhi:
                out.append((lo, hi))
                continue
            if lo < hlo:
                out.append((lo, hlo - 1))
            if hi > hhi:
                out.append((hhi + 1, hi))
        return out

    def total_length(self, ranges):
        """ranges 覆盖的整数个数之和（闭区间含端点；重叠只算一次）。"""
        return sum(hi - lo + 1 for lo, hi in self.merge(ranges))
"}

{"path": "units/flags/flags.py", "content": """"命令行风格的参数解析。"""


class Impl:
    def parse(self, argv):
        """返回 {"values": {...}, "flags": {...}, "positional": [...]}：
        - 不以 "-" 开头、或正好是 "-" 的项，按出现顺序进 positional。
        - `--` 之后的所有项都是位置参数（`--` 自己不出现在结果里）。
        - `--key=value` 与 `--key value` 都是键值对，键是 key。
        - `--key` 后面没有可用值（到结尾，或后面紧跟另一个 "--" 开头的项）时它是开关。
        - `-abc` 是三个开关 a、b、c。
        - values 的每个值是**列表**，重复的键按出现顺序累积；开关重复出现仍是 True。
        """
        values = {}
        flags = {}
        positional = []

        i = 0
        n = len(argv)
        while i < n:
            item = argv[i]

            if item == "--":
                positional.extend(argv[i + 1:])
                break

            if item.startswith("--"):
                body = item[2:]
                if "=" in body:
                    key, value = body.split("=", 1)
                    values.setdefault(key, []).append(value)
                else:
                    key = body
                    if i + 1 < n and not argv[i + 1].startswith("--"):
                        values.setdefault(key, []).append(argv[i + 1])
                        i += 1
                    else:
                        flags[key] = True
            elif item.startswith("-") and item != "-":
                for ch in item[1:]:
                    flags[ch] = True
            else:
                positional.append(item)

            i += 1

        return {"values": values, "flags": flags, "positional": positional}
"}

{"path": "units/measure/measure.py", "content": "class Impl:
    _FACTORS = {"m": 100, "cm": 1, "mm": 0.1}

    def to_cm(self, value, unit):
        """把 value（给定单位）换算成厘米；非法单位抛 ValueError。"""
        if unit not in self._FACTORS:
            raise ValueError(f"unknown unit: {unit!r}")
        return value * self._FACTORS[unit]
